test("resolves a normal file name", () => {
  assert.equal(resolveUserFile("avatar.png"), `${BASE_DIR}/avatar.png`);
  assert.equal(resolveUserFile("report-2026.v2.tar.gz"), `${BASE_DIR}/report-2026.v2.tar.gz`);
  assert.equal(resolveUserFile("100%.png"), `${BASE_DIR}/100%.png`);
});

test("rejects path traversal names", () => {
  for (const name of ["../etc/passwd", "../../etc/passwd", "..", ".", "/etc/passwd", "sub/file.png", "..\\..\\windows\\system32"]) {
    assert.throws(() => resolveUserFile(name), new RegExp(ERROR_INVALID_FILE_NAME), name);
  }
});

test("rejects encoded path traversal names", () => {
  for (const name of [
    "%2e%2e%2fetc%2fpasswd",
    "%2E%2E%5C..%5Cwindows",
    "..%2f..%2fetc%2fpasswd",
    "%252e%252e%252fetc%252fpasswd",
    "%2fetc%2fpasswd",
  ]) {
    assert.throws(() => resolveUserFile(name), new RegExp(ERROR_INVALID_FILE_NAME), name);
  }
});

